-- Legal documents — privacy policy, ToS, etc. Stored as Markdown content
-- editable by admin via /admin/legal/{doc_id}. One row per document.
--
-- Why a table and not a file:
--   • Admin can edit through the UI without a deploy.
--   • updated_at lets the frontend show "последнее обновление: ..." line.
--   • S3 daily pg_dump backup covers content recovery for free.

CREATE TABLE IF NOT EXISTS legal_documents (
    doc_id      TEXT PRIMARY KEY,
    title       TEXT NOT NULL,
    content     TEXT NOT NULL,          -- Markdown
    version     INTEGER NOT NULL DEFAULT 1,
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by  TEXT                     -- client_id of admin who last edited
);

-- Seed default privacy policy. ON CONFLICT keeps subsequent migrations
-- idempotent if the row was already inserted by a prior run. The admin
-- is expected to edit this through the UI; this seed is a starting
-- point with the structure / sections a Russian-jurisdiction service
-- typically needs (152-ФЗ compliant in spirit).
INSERT INTO legal_documents (doc_id, title, content) VALUES (
    'privacy',
    'Политика конфиденциальности',
    E'# Политика конфиденциальности\n\nНастоящая Политика определяет порядок обработки персональных данных пользователей сервиса прогнозирования SKU («Сервис»). Используя Сервис, вы соглашаетесь с условиями настоящей Политики.\n\n## 1. Какие данные мы собираем\n\n- **Email** — для регистрации, авторизации (одноразовый код) и операционных уведомлений.\n- **Идентификатор организации** (client_id) — выбираете вы при регистрации.\n- **Загружаемые файлы** — CSV/Parquet с историей продаж и SKU. Содержимое принадлежит вам.\n- **Технические данные**: IP-адрес сессии, тип браузера, время обращений — для безопасности и диагностики.\n- **OAuth-данные** при входе через Google/Yandex: только email и идентификатор учётной записи провайдера.\n\n## 2. Как мы используем данные\n\n- Обеспечение работы Сервиса: построение моделей прогноза, сохранение результатов, доступ к личному кабинету.\n- Информирование о статусе обучения моделей и важных событиях через email или Telegram (при добавлении).\n- Предотвращение злоупотреблений: rate-limit, лог попыток входа, защита от перебора паролей.\n- Улучшение качества Сервиса: агрегированная аналитика без идентификации конкретных пользователей.\n\n## 3. Передача данных третьим лицам\n\nМы не продаём и не передаём ваши персональные данные третьим лицам, за исключением:\n\n- Облачных провайдеров инфраструктуры (Yandex Cloud, Beget) — для хранения зашифрованных резервных копий.\n- Сервиса Cloudflare — для защиты от DDoS и доставки статики.\n- Случаев, прямо предусмотренных законодательством РФ (по запросу государственных органов в установленном порядке).\n\nВсе передачи происходят по защищённому каналу (TLS 1.2+).\n\n## 4. Хранение и защита\n\n- Данные хранятся на серверах в РФ.\n- Пароли не хранятся в открытом виде — авторизация по одноразовым кодам или OAuth.\n- API-ключи хранятся в виде bcrypt-хэшей.\n- Загруженные файлы шифруются в S3 (AES-256).\n- Бэкапы базы данных шифруются и удаляются автоматически через 30 дней.\n- Доступ к продакшн-системам ограничен и логируется.\n\n## 5. Срок хранения\n\n- Данные учётной записи — пока действует ваш аккаунт + 30 дней после удаления.\n- Загруженные файлы — пока вы их не удалите через интерфейс Сервиса.\n- Логи безопасности (попытки входа, аудит) — до 90 дней.\n- Прогнозы — пока существует учётная запись.\n\n## 6. Ваши права\n\nВ соответствии со 152-ФЗ «О персональных данных» вы имеете право:\n\n- Получить копию хранящихся о вас данных.\n- Потребовать исправления или удаления данных.\n- Отозвать согласие на обработку данных (приведёт к закрытию учётной записи).\n- Обратиться в Роскомнадзор при нарушении ваших прав.\n\nДля реализации этих прав напишите на адрес поддержки.\n\n## 7. Cookies и аналогичные технологии\n\nСервис использует функционально необходимые cookies для поддержания сессии после входа. Сторонние трекеры и рекламные cookies не устанавливаются.\n\n## 8. Изменения политики\n\nМы можем обновлять настоящую Политику. Существенные изменения мы анонсируем через email-уведомление за 14 дней до вступления в силу. Дата последнего обновления указана внизу документа.\n\n## 9. Контакты\n\nПо вопросам обработки персональных данных: **dochub.org@gmail.com**.\n\nОператор: ИП / ООО [укажите реквизиты].'
)
ON CONFLICT (doc_id) DO NOTHING;
